import{_ as s}from"./index-dOcyQ9H1.js";import{az as l}from"./@vue-De9RwyRn.js";import"./element-plus-CKJIAC2w.js";import"./lodash-es-Ceiv_TW4.js";import"./@vueuse-Ihwzeb_o.js";import"./@element-plus-B-y2LHuz.js";import"./async-validator-j0i5Y79Y.js";import"./@popperjs-DxtSUbXb.js";import"./@ctrl-DGnlsNIE.js";import"./dayjs-KsS9adaU.js";import"./memoize-one-BAtLgO95.js";import"./normalize-wheel-es-TzhA1irr.js";import"./@floating-ui-BQjuueHq.js";import"./pinia-Dndd2XNl.js";import"./crypto-js-B6L3KfD1.js";import"./vue-i18n-DB7lm_w-.js";import"./@intlify-D8hALvN4.js";import"./vue-router-DNsliMEH.js";import"./pinia-plugin-persistedstate-COWkwNh5.js";const i=s({},[["render",function(s,i){return i[0]||(i[0]=l('<div class="helpBoxTop">一、普通事件</div><div class="helpBoxTopChild">移动侦测</div><div class="helpDesText" style="margin-top:8px;"> 移动侦测功能常用于无人值守监控录像和自动报警，具体设置步骤如下所示。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：基本设置：勾选“启用移动侦测”可开启网动侦测功能。 <ul><li> 勾选“启用动态分析”表示在移动侦测功能和“规则信息”均启用下，对布防区域内的移动目标进行标定。 </li><li>当设置动态分析后且画面中有移动物体时，侦测的区域将显示绿色方格。</li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤2：区域设置：单击“绘制区域”，在画面中单击鼠标左键并拖动鼠标，然后松开鼠标左键，即完成一个区域的绘制，绘制完毕后单击“停止绘制。 <ul><li>您可单击“清除全部清除区域；</li><li>同时可拖动进度条设置区域的灵敏度，数字越高灵敏度越高；</li><li>当灵敏度为0时，移动侦测和动态分析将不起作用</li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤3：布防时间设置：单击“编辑进入布防时间设置，设置移动侦测的布防时间。 <ul><li>布防时间可以设置整个星期或者一个星期的某一天的某个时间段</li><li>一天可以进行8个时间段的开始时间和结束时间的详细设置</li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：联动方式设置: 移动侦测时可以开启报警联动,联动方式包括&quot;常规联动&quot;和&quot;其他联动&quot;,请根据自身的需求设置联动方式 </div><div class="helpDesTxt">步骤5：设置完毕后单击&quot;保存&quot;, 完成设置</div><div class="helpBoxTopChild">遮挡报警</div><div class="helpDesText" style="margin-top:8px;"> 遮挡报警是指当定义的遮挡报警区域被人为等因素遮挡，致使无法对该区域进行正常地监控时产生的报警。当遮挡报警产生后，您可以迅速排查遮挡报警原因，还原监控画面。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：勾选“启用遮挡报警”可开启网络摄像机遮挡报警功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：区域设置：单击“绘制区域”，在画面中单击鼠标左键并拖动鼠标，然后松开鼠标左键，即完成区域的绘制；绘制完毕后单击“停止绘制”。您可单击“清除全部”清除区域；同时可拖动进度条设置区域的灵敏度，越往右滑动灵敏度越高。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：布防时间设置：设置遮挡报警的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤4：联动方式设置：遮挡报警可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpDesTxt">步骤5：设置完毕后单击“保存”，完成设置。</div><div class="helpBoxTopChild">视频丢失报警</div><div class="helpDesText" style="margin-top:8px;"> 当视频信号丢失而看不到监控面面时，您可以设置丢失联动报警，此时即可快速排查丢失原因进而进行恢复。具体配置步骤如下所示。 </div><div class="helpDesText" style="margin-top:8px;"> 1.勾选“启用视频丢失”可开启智能球视频丢失报警功能。 </div><div class="helpDesText" style="margin-top:8px;"> 2.布防时间设置：设置视频丢失的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesText" style="margin-top:8px;"> 3.联动方式设置：视频丢失可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpDesTxt">4.设置完毕后单击“保存”，完成设置。</div><div class="helpBoxTopChild">报警输入</div><div class="helpDesText" style="margin-top:8px;"> 设备支持开关量报警，当有开关量报警时对该报警进行报警处理。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：选择需要设置的报警输入号，然后设置其名称及类型。报警名称可自定义，报警类型可设置为常开和常闭。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：配置报警输入，可配置为不启用、作为报警输入和一键撤防。 </div><div class="helpDesTxt"> 说明： 仅报警输入1支持配置“一键撤防”。配置一键撤防并保存，配置的联动即时生效，如配置一键撤防联动上传中心，则在启用后，设备所有告警不再上传中心。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：布防时间设置：设置报警输入的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesTxt"> 步骤4：联动方式设置：报警输入可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpBoxTopChild">报警输出</div><div class="helpDesText" style="margin-top:8px;"> 当报警发生时，可以通过声音警告（蜂鸣声）、上传中心（主动将报警信号发送给运行在远程的报警主机（安装网络视频监控软件的PC））、联动报警输出、发送报警邮件警示、联动PTZ等。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：选择设置的报警输出号，设置其报警名称和报警持续时间。具体延时时间，您可以根据实际情况而定。可设置5秒~10分的持续时间，也可设置为“手动”，即手动来关闭报警输出。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：配置报警输入，可配置为不启用、作为报警输入和一键撤防。 </div><div class="helpDesTxt"> 说明： 仅报警输入1支持配置“一键撤防”。配置一键撤防并保存，配置的联动即时生效，如配置一键撤防联动上传中心，则在启用后，设备所有告警不再上传中心。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：布防时间设置：设置报警输入的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesTxt"> 步骤4：单击“确定”完成布防时间的设置。若其他报警输出设置一致，您可进行复制，设置完毕后单击“保存”。 </div><div class="helpBoxTopChild">异常</div><div class="helpDesText" style="margin-top:8px;"> 异常配置是对异常事件的告警处理，异常事件包括硬盘满（有硬盘空间录满时）、硬盘错误（写硬盘时出错或硬盘没有初始化）、网络断开（没有连接网线）、IP冲突、非法访问（用户名、密码错误）、录像/抓图异常（如无录像硬盘等）、阵列异常、热备异常等。 </div><div class="helpDesTxt"> 异常报警的联动方式包括“常规联动”和“其他联动”。参数配置完毕后单击“保存”保存相关设置。 </div><div class="helpBoxTopChild">闪光灯报警输出</div><div class="helpDesText" style="margin-top:8px;"> 当接入声光报警相机时，可在Web配置闪光报警灯的闪烁时间、频率和布防时间。 </div><div class="helpDesText" style="margin-top:8px;">步骤1：选择通道号。</div><div class="helpDesText" style="margin-top:8px;">步骤2：设置闪烁时间和闪烁频率。</div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置闪光灯报警输出的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesText" style="margin-top:8px;">步骤4：单击“保存”完成设置。</div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">声音报警输出</div><div class="helpDesText" style="margin-top:8px;"> 当接入声光报警相机时，可在Web配置声音报警输出的相关参数和布防时间。 </div><div class="helpDesText" style="margin-top:8px;">步骤1：选择通道号。</div><div class="helpDesText" style="margin-top:8px;"> 步骤2：选择“音频类型”为“警戒音”、“提示音”或“自定义语音”。 </div><div class="helpDesText" style="margin-top:8px;">步骤3：配置声音报警输出参数。</div><div class="helpDesText" style="margin-top:8px;"> 警戒音：选择警戒音类型，设置警戒音报警次数和外放音量。 </div><div class="helpDesText" style="margin-top:8px;">提示音：设置提示音报警次数和外放音量。</div><div class="helpDesText" style="margin-top:8px;"> 自定义语音：单击“添加”，上传自定义语音并输入语音名称，在“自定义语音”下拉框中选择已上传的自定义语音，设置自定义语音的报警次数和外放音量。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置声音报警输出的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesText" style="margin-top:8px;">步骤5：单击“保存”完成设置。</div><div class="helpBoxTop">二、周界事件</div><div class="helpDesTxt"> 支持越界侦测、区域入侵侦测、进入区域侦测、离开区域侦测四种事件的配置。 </div><div class="helpBoxTopChild">越界侦测</div><div class="helpDesText" style="margin-top:8px;"> 越界侦测功能视具体型号而定。越界侦测功能可侦测视频中是否有物体跨越设置的警戒面，根据判断结果联动报警。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：启用越界侦测。当您配置了越界侦测参数后，勾选表示启用该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒面、警戒区域和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “方向”：是指物体穿越警戒面触发报警的方向。“A-&gt;B”表示物体从A越界到B时将触发报警，“B-&gt;A”表示物体从B越界到A时将触发报警，“A&lt;-&gt;B”表示双向触发报警。 </li><li> “灵敏度”：共1-100可选，用于设置控制目标物体的大小，灵敏度越高时越小的物体越容易被判定为目标物体，灵敏度越低时较大物体才会被判定为目标物体。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：布防时间设置：设置越界侦测的布防时间。布防时间可以设置整个星期或者一个星期的某一天的某个时间段；一天可设置多个布防时间段。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：联动方式设置：越界侦测可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：所有参数设置完毕后，单击“保存”完成越界侦测的配置。 </div><div class="helpDesTxt"></div><div class="helpBoxTopChild">区域入侵侦测</div><div class="helpDesText" style="margin-top:8px;"> 区域入侵侦测功能可侦测视频中是否有物体入侵设置的禁区，该功能可供用户建立最多4区域的四边形警戒区，当有目标物体进入该区域时，设备可产生报警信号并做相关联动。具体设置步骤如下所示。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：启用区域入侵侦测。当您配置了区域入侵侦测参数后，勾选表示启用该功能 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “时间阀值”：表示目标进入警戒区域持续停留该时间后产生报警。例如设置为0，即目标入侵区域后立即触发报警。最长为10秒 </li><li> “灵敏度”：用于设置控制目标物体的大小，灵敏度越高越小运动的目标物体越容易被侦测，灵敏度越低越大运动的目标物体越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“上传中心”、“邮件联动”、“录像联动”。其他联动可以选择PTZ、声光报警等。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成区域入侵侦测的配置。 </div><div class="helpDesTxt"></div><div class="helpBoxTopChild">进入区域侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测是否有物体进入指定的侦测区域，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用进入区域侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “灵敏度”：用于设置控制目标物体的大小，灵敏度越高越小运动的目标物体越容易被侦测，灵敏度越低越大运动的目标物体越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“上传中心”、“邮件联动”、“录像联动”。其他联动可以选择PTZ、声光报警等。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成进入区域侦测的配置。 </div><div class="helpDesTxt"></div><div class="helpBoxTopChild">离开区域侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测是否有物体离开指定的侦测区域，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用离开区域侦测”来开启该功能 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “灵敏度”：用于设置控制目标物体的大小，灵敏度越高越小运动的目标物体越容易被侦测，灵敏度越低越大运动的目标物体越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“上传中心”、“邮件联动”、“录像联动”。其他联动可以选择PTZ、声光报警等。 </div><div class="helpDesTxt">步骤6：参数修改后，单击“保存”完成离开区域侦测的配置。</div><div class="helpBoxTop">三、行为分析</div><div class="helpBoxTopChild">徘徊侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测目标在进入指定的侦测区域内运动，持续运动时间超过设定的时间，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用徘徊侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域、时间阈值和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “时间阈值”：表示目标在侦测区域内持续运动的时间，时间阈值设置越大，目标在侦测区域内持续运动的时间越长才能触发。 </li><li> “灵敏度”：用于设置控制目标物体的大小，灵敏度越高越小运动的目标物体越容易被侦测，灵敏度越低越大运动的目标物体越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“声音报警”、“邮件联动”、“上传中心”、“监视器上警告”。其他联动可以选择对应的报警输出通道。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成徘徊侦测的配置。 </div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">人员聚集侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测指定的侦测区域内人员密集程度超过设定的比例阈值，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用人员聚集侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域和占比。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “占比”：表示在侦测区域内人员密度达到侦测区域的密度比例，占比设置越小越容易触发。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“声音报警”、“邮件联动”、“上传中心”、“监视器上警告”。其他联动可以选择对应的报警输出通道。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成人员聚集侦测的配置。 </div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">停车侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测指定的侦测区域内车辆停留时间超过设定的时间，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用停车侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域、时间阈值和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “时间阈值”：表示在侦测区域内入侦测停止不动的车辆或物体的时间，时间阈值设置越大，目标在侦测区域内停留的时间越长才能触发。 </li><li> “灵敏度”：用于设置控制报警触发的灵敏度，灵敏度越高,目标区域中的物体变动越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“声音报警”、“邮件联动”、“上传中心”、“监视器上警告”。其他联动可以选择对应的报警输出通道。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成停车侦测的配置。 </div><div class="helpBoxTop">三、行为分析</div><div class="helpBoxTopChild">音频异常侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测声音的强度。对于拾音器断开、超过一定声音强度阈值或超过一定声音突变的变化量阈值可实现自动预警功能，并联动报警。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：勾选“音频输入异常”，开启音频输入异常侦测功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：按实际需求勾选“声强陡升”，并设置其灵敏度和声音强度阈值。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：按实际需求勾选“声强陡降”，并设置其灵敏度。 <ul><li> “声强陡升”：勾选“声强陡升”表示启用侦测音频源强度是否突然升高，根据判断结果联动报警。 </li><li> “灵敏度”：数值越小，则输入声音强度变化超过持续环境音量更多才能被判断为音频异常，用户需要根据实际环境测试调节。灵敏度可设置区间范围：1-100。 </li><li> “声音强度阈值”：当声强突变类型选择为“声强陡升”时，可设置该参数。用于设置过滤的环境声音强度，如果环境噪音越大，则该值需要设置的越高，用户需要根据实际环境测试调节。声音强度阈值可设置区间范围：1-100。 </li><li> “声强陡降”：勾选声强陡降表示启用侦测音频源强度是否突然降低，根据判断结果联动报警。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：布防时间设置：设置音频异常侦测的布防时间。 <ul><li>布防时间可以设置整个星期或者一个星期的某一天的某个时间段；</li><li>一天可以进行8个时间段的开始时间和结束时间的详细设置。</li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤5：联动方式设置：音频异常侦测时可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpDesText" style="margin-top:8px;">步骤6：设置完毕后单击“保存”，完成设置。</div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">场景变更侦测</div><div class="helpDesText" style="margin-top:8px;"> 如果监控设备由于受到外部干扰或者人为破坏而造成监控场景发生改变，将会使监控系统无法有效运作，从而使被监控场景面临安全风险。该功能可以分析被监控的场景是否发生变更，一旦发生变更则会触发报警，并联动报警。 </div><div class="helpDesText" style="margin-top:8px;">步骤1：勾选“启用”，开启场景变更侦测功能。</div><div class="helpDesText" style="margin-top:8px;"> 步骤2：按实际需求设置灵敏度。 <ul><li> “灵敏度”：用于设置控制目标物体的大小，灵敏度越高时越小的物体越容易被判定为目标物体，灵敏度越低时较大物体才会被判定为目标物体。灵敏度可设置区间范围：1-100。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤3：布防时间设置：设置场景变更侦测的布防时间。 <ul><li>布防时间可以设置整个星期或者一个星期的某一天的某个时间段；</li><li>一天可以进行8个时间段的开始时间和结束时间的详细设置。</li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：联动方式设置：场景变更侦测时可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。 </div><div class="helpDesText" style="margin-top:8px;">步骤5：设置完毕后单击“保存”，完成设置。</div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">物品遗留侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测指定的侦测区域内物品被遗留的时间超过设定的时间，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用物品遗留侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域、时间阈值和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “时间阈值”：表示在侦测区域内目标物体有遗留要达到的时间，时间阈值设置越大，目标物体在侦测区域内遗留的时间越长才能触发。 </li><li> “灵敏度”：用于设置控制报警触发的灵敏度，灵敏度越高,目标区域中的物体变动越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“声音报警”、“邮件联动”、“上传中心”、“监视器上警告”。其他联动可以选择对应的报警输出通道。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成物品遗留侦测的配置 </div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">物品拿取侦测</div><div class="helpDesText" style="margin-top:8px;"> 该功能可检测指定的侦测区域内物品被拿取的时间超过设定的时间，自动产生报警联动。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤1：用户可以在该界面勾选“启用物品拿取侦测”来开启该功能。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤2：绘制警戒区域：在预览界面中依次单击鼠标左键绘制四边形警戒区的端点，绘制完毕后单击鼠标右键完成区域绘制。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤3：设置警戒参数：包括选择警戒区域、时间阈值和灵敏度。 <ul><li>“警戒区域”：选择不同“警戒区域”编号可设置不同的警戒区域。</li><li> “时间阈值”：表示在侦测区域内目标物体被拿取要达到的时间，时间阈值设置越大，目标物体在侦测区域内被拿取的时间越长才能触发。 </li><li> “灵敏度”：用于设置控制报警触发的灵敏度，灵敏度越高,目标区域中的物体变动越容易被侦测。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 步骤4：设置布防时间：所有“警戒区域”使用同一个布防时间，在设置的布防时间内，联动方式才生效。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤5：设置联动方式：常规联动包括“声音报警”、“邮件联动”、“上传中心”、“监视器上警告”。其他联动可以选择对应的报警输出通道。 </div><div class="helpDesText" style="margin-top:8px;"> 步骤6：参数修改后，单击“保存”完成物品拿取侦测的配置。 </div><div class="helpBoxTop">四、目标检测</div><div class="helpBoxTopChild">人脸侦测</div><div class="helpDesText" style="margin-top:8px;">该功能可用于侦测出场景中出现的人脸</div><div class="helpDesText" style="margin-top:8px;">1、进入“配置→事件→目标检测→人脸侦测”。</div><div class="helpDesText" style="margin-top:8px;"> 2、勾选“启用人脸侦测”可开启网络摄像机人脸侦测功能。 </div><div class="helpDesText" style="margin-top:8px;"> 3、勾选“启用动态分析”表示当在人脸侦测功能和“规则信息”均启用下，对布防区域内的人脸进行动态分析。当设置动态分析后且画面中有侦测到人脸时，画面中的人脸将被绿色方框框定。 </div><div class="helpDesText" style="margin-top:8px;"> 4、按实际需求设置灵敏度。 <ul><li> 灵敏度：用于设置控制目标物体的大小，灵敏度越高时越小的物体越容易被判定为目标物体，灵敏度越低时较大物体才会被判定为目标物体。灵敏度可设置区间范围：1-100。 </li></ul></div><div class="helpDesText" style="margin-top:8px;">5、布防时间设置</div><div class="helpDesText" style="margin-top:8px;"> 在“布防时间”内可显示并设置布防时间，默认为全天布防，可通过以下方式调整布防时间： </div><div class="helpDesText" style="margin-top:8px;"><ul><li> 方法一：单击“布防图标”，手动绘制开始和结束时间。设置完成后，点击保存。如果需要删除某个时间段，请单击“橡皮擦”工具进行擦除，然后重新设置时间段。 </li><li> 方法二：单击“编辑”跳出“编辑计划弹窗”选择对应的日期以及布防的时间，时间格式：HH:mm；点击“复制到”跳出“复制窗口”选择需要复制的通道，通道只显示在线通道，已配置的通道置灰; </li> 其余说明： <li>①同一天的时间轴上可设置多个时间段，最多可支持 8 个时间段设置。</li><li> ②当前日期的布防时间设置完毕后，若其他时间也需要设置成相同的布防时间，单击时间轴右侧的“复制按钮“，“复制到”对应的日期里。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 6、设置联动方式：联动方式是指产生报警事件时设备做出的反应，场景变更侦测时可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。请根据需求设置联动方式，报警联动的方式说明请参见“移动侦测配置”。 </div><div class="helpDesText" style="margin-top:8px;">7、所有参数修改后，单击“保存”。</div><div class="helpDesText" style="margin-top:8px;"></div><div class="helpBoxTopChild">宠物识别</div><div class="helpDesText" style="margin-top:8px;">1、进入“配置→事件→Smart 事件→宠物识别”。</div><div class="helpDesText" style="margin-top:8px;"> 2、勾选“启用宠物识别”可开启网络摄像机宠物识别功能。 </div><div class="helpDesText" style="margin-top:8px;"> 3、勾选“启用动态分析”表示当在宠物识别功能和“规则信息”均启用下，对布防区域内的宠物进行动态分析。当设置动态分析后且画面中有侦测到宠物时，画面中的宠物将被绿色方框框定。 </div><div class="helpDesText" style="margin-top:8px;"> 4、按实际需求设置灵敏度。 <ul><li> 灵敏度：用于设置控制目标物体的大小，灵敏度越高时越小的物体越容易被判定为目标物体，灵敏度越低时较大物体才会被判定为目标物体。灵敏度可设置区间范围：1-100。 </li></ul></div><div class="helpDesText" style="margin-top:8px;">5、布防时间设置</div><div class="helpDesText" style="margin-top:8px;"> 在“布防时间”内可显示并设置布防时间，默认为全天布防，可通过以下方式调整布防时间： </div><div class="helpDesText" style="margin-top:8px;"><ul><li> 方法一：单击“布防图标”，手动绘制开始和结束时间。设置完成后，点击保存。如果需要删除某个时间段，请单击“橡皮擦”工具进行擦除，然后重新设置时间段。 </li><li> 方法二：单击“编辑”跳出“编辑计划弹窗”选择对应的日期以及布防的时间，时间格式：HH:mm；点击“复制到”跳出“复制窗口”选择需要复制的通道，通道只显示在线通道，已配置的通道置灰; </li> 其余说明： <li>①同一天的时间轴上可设置多个时间段，最多可支持 8 个时间段设置。</li><li> ②当前日期的布防时间设置完毕后，若其他时间也需要设置成相同的布防时间，单击时间轴右侧的“复制按钮“，“复制到”对应的日期里。 </li></ul></div><div class="helpDesText" style="margin-top:8px;"> 6、设置联动方式：联动方式是指产生报警事件时设备做出的反应，场景变更侦测时可开启报警联动，联动方式包括“常规联动”和“其他联动”，请根据自身的需求设置联动方式。请根据需求设置联动方式，报警联动的方式说明请参见“移动侦测配置”。 </div><div class="helpDesText" style="margin-top:8px;">7、所有参数修改后，单击“保存”。</div><div class="helpDesText" style="margin-top:8px;"></div>',178))}]]);export{i as default};
